/**
 * Runs the innetjs client build with the CSS generated by buildEnv.ts.
 *
 * The agent host process may already carry INNETJS_CSS from another DSH
 * plugin (the release bundle copies its theme into process.env). dotenv does
 * not override existing variables, so without this wrapper that stale value
 * would win over `.env.theme` and the client would ship another plugin's
 * stylesheet.
 */

import { spawnSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'

import * as dotenv from 'dotenv'

const env = { ...process.env }

if (existsSync('.env.theme')) {
  const theme = dotenv.parse(readFileSync('.env.theme', 'utf8'))

  if (typeof theme.INNETJS_CSS === 'string') env.INNETJS_CSS = theme.INNETJS_CSS
}

const command = process.platform === 'win32' ? 'innetjs.cmd' : 'innetjs'
const result = spawnSync(
  command,
  ['build', '-i', 'client', '-tc', '-lc', '-e'],
  { env, stdio: 'inherit' },
)

process.exit(result.status === null ? 1 : result.status)
